d={}
for s in U:
 p='../persistent/stock_data/'+s+'.csv'; x=pd.read_csv(p,parse_dates=['date']).set_index('date')['close'].sort_index(); d[s]=x
px=pd.DataFrame(d).sort_index(); r=np.log(px).diff(); dates=px.index
# beta-neutral residual cumulative return: regress asset daily returns on equal-weight benchmark over prior 60 sessions
for win in [40,60,100]:
 for look in [10,20]:
  for h in [5,10,20]:
   vals=[]; fwd=[]; nms=[]
   for i in range(max(win,look)+2,len(dates)-h-1):
    hist=r.iloc[i-win:i]; bench=hist.mean(axis=1)
    row=[]; fr=[]
    for s in U:
     z=pd.concat([hist[s],bench],axis=1).dropna()
     if len(z)<max(20,win//2): row.append(np.nan); fr.append(np.nan); continue
     beta=np.cov(z.iloc[:,0],z.iloc[:,1],ddof=1)[0,1]/(np.var(z.iloc[:,1],ddof=1)+1e-12)
     resid=z.iloc[:,0]-beta*z.iloc[:,1]
     row.append(resid.iloc[-look:].sum())
     fr.append(r[s].iloc[i+1:i+1+h].sum())
    q=pd.DataFrame({'f':row,'y':fr}).dropna()
    if len(q)>=8:
     vals.append(spearmanr(q.f,q.y).statistic); fwd.append(q.y.mean()); nms.append(len(q))
