 for i,dt in enumerate(sig.index):
  if start and dt<pd.Timestamp(start): continue
  z=pd.concat([sig.loc[dt],y.loc[dt]],axis=1).dropna()
  if len(z)>=8:
   a=spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic; vals.append(a); ns.append(len(z))
   if i: tr.append((sig.loc[dt].rank(pct=True)-sig.shift(1).loc[dt].rank(pct=True)).abs().mean())
 a=np.array(vals)
 return len(a),np.mean(ns),a.mean(),a.mean()/(a.std(ddof=1)+1e-12)*np.sqrt(len(a)),np.mean(a>0),np.nanmean(tr)
for h in [1,5,10,20]:
 for label,start in [('full',None),('recent252','2029-06-01'),('recent120','2030-01-01')]:
  x=ev(h,start); print(f'{label} h={h} dates={x[0]} avgN={x[1]:.2f} IC={x[2]:.6f} ICIR={x[3]:.6f} hit={x[4]:.4f} turnover={x[5]:.6f}')
print('assets',px.shape[1],'dates',px.index.min().date(),px.index.max().date())

