P=pd.DataFrame(P); V=pd.DataFrame(V)
ret=P.pct_change(20); vt=np.log(V.rolling(10,min_periods=5).mean()/V.rolling(60,min_periods=20).mean()); fac=(ret*(1+0.35*np.tanh(vt))).shift(1); rows=[]
for h in [1,5,10,20]:
