F={'raw':-ratio,'log':-np.log(ratio),'demean':-(ratio-ratio.median(axis=1).values[:,None]),'scaled':-(ratio-1)*r.rolling(20).std()}
def calc(f,H,st=0):
 a=[]; ns=[]
