for a in A:
 f='../persistent/stock_data/'+a+'.csv'
 if os.path.exists(f): px[a]=pd.read_csv(f,parse_dates=['date']).set_index('date').close.astype(float)
P=pd.DataFrame(px).sort_index().loc[:'2033-12-07']; R=P.pct_change(); v20=R.rolling(20,min_periods=15).std(); v60=R.rolling(60,min_periods=40).std()
# Reversal after an unusually volatile recent move: negative return, weighted by volatility shock, lagged.
shock=(v20/v60).clip(0.25,4); F=(-P.pct_change(20)*shock).shift(1)
rows=[]
for dt in F.index:
 y=P.shift(-10).loc[dt]/P.loc[dt]-1; z=pd.concat([F.loc[dt],y],axis=1).dropna()
